// Round-5 spike: split a <ul>/<ol> around embedded block-level content (a
// fenced <pre>, or an image-bearing <img>/<figure>/<picture>/<svg>) that
// Turndown's list rule cannot express as list-item text. Operates on a
// cheerio $ the caller already loaded; every element returned is a fresh
// clone, so the original tree is left untouched.

const BLOCK_TAGS = new Set(["pre", "img", "figure", "picture", "svg"]);

export function hasSplittableBlock($, listEl) {
  return $(listEl).find("pre, img, figure, picture, svg").length > 0;
}

function wrapBarePre($, pre) {
  const $pre = $(pre);
  const elementChildren = $pre.children();
  const alreadyWrapped = elementChildren.length === 1 && elementChildren.get(0).name === "code";
  if (alreadyWrapped) {
    return $pre.clone().get(0);
  }
  const code = $("<code></code>");
  code.append($pre.clone().contents());
  const wrapped = $("<pre></pre>");
  wrapped.append(code);
  return wrapped.get(0);
}

function toBlockSegment($, block) {
  const tag = block.name;
  if (tag === "pre") {
    return { type: "code", el: wrapBarePre($, block) };
  }
  if (tag === "img") {
    return { type: "image", src: $(block).attr("src"), alt: $(block).attr("alt") ?? "" };
  }
  if (tag === "svg") {
    return { type: "image", src: undefined, alt: $(block).attr("aria-label") ?? "" };
  }
  // figure / picture: the image inside carries src/alt.
  const img = $(block).find("img").first();
  return { type: "image", src: img.attr("src"), alt: img.attr("alt") ?? "" };
}

function findOwnBlock(node) {
  return node.type === "tag" && BLOCK_TAGS.has(node.name) ? node : null;
}

// Splits one <li>'s own content (excluding any nested list child, which is
// recursed into separately) into an ordered run of segments: {type:"li", el}
// for content that stays wrapped in a (possibly new) <li>, or a bare
// {type:"code"|"image", ...} for a block that breaks out of the item. An
// item whose sole content is the block emits no <li> segment around it at
// all — that is what keeps it from being duplicated.
function splitLi($, liEl, toMarkdown) {
  const segments = [];
  let currentLiNodes = [];

  // A run of nodes that is only whitespace text (the pretty-printing
  // between a closing nested list and the </li>, once that list has been
  // pulled out into its own segment) carries no content — flushing it would
  // manufacture a spurious empty <li> that duplicates nothing.
  const isMeaningful = (node) => !(node.type === "text" && node.data.trim() === "");

  const flushLi = () => {
    if (!currentLiNodes.some(isMeaningful)) {
      currentLiNodes = [];
      return;
    }
    const clone = $("<li></li>");
    currentLiNodes.forEach((n) => clone.append(n));
    segments.push({ type: "li", el: clone.get(0) });
    currentLiNodes = [];
  };

  const nodes = $(liEl).contents().toArray();

  nodes.forEach((node) => {
    if (node.type === "tag" && (node.name === "ul" || node.name === "ol")) {
      const nested = splitListNode($, node, toMarkdown);
      if (nested.length === 1 && nested[0].type === "list") {
        currentLiNodes.push(nested[0].el);
        return;
      }
      // The nested list itself split: its first fragment continues this
      // item (append it, then close the item here); every later fragment
      // breaks out — a further "list" fragment resumes wrapped in a fresh,
      // otherwise-empty <li> at THIS level (this item's own text already
      // left in the first fragment), a bare code/image fragment surfaces
      // unwrapped as its own top-level segment.
      const [first, ...rest] = nested;
      if (first && first.type === "list") {
        currentLiNodes.push(first.el);
      }
      flushLi();
      rest.forEach((seg) => {
        if (seg.type === "list") {
          const stub = $("<li></li>");
          stub.append(seg.el);
          segments.push({ type: "li", el: stub.get(0) });
        } else {
          segments.push(seg);
        }
      });
      return;
    }

    const block = findOwnBlock(node);
    if (block) {
      flushLi();
      segments.push(toBlockSegment($, block));
      return;
    }

    currentLiNodes.push($(node).clone().get(0) ?? node);
  });

  flushLi();
  return segments;
}

// Splits one <ul>/<ol> around embedded blocks, returning an ordered array of
// {type:"list", el} (a clone carrying a contiguous run of the original
// <li>s, numbered via `start` so an ordered list resumes at the right
// number) interleaved with bare {type:"code"|"image", ...} segments. A list
// with no embedded block at any depth returns exactly one {type:"list"}
// segment, equivalent to the original (still a clone).
