// Declares every child of the article as one unit, a <pre> as code and
// anything else as a paragraph, the way a well-behaved recipe does.
function childrenRecipe(title: string): string {
  return `
export const container = "article";
export function extract($, toMarkdown) {
  const units = $("article").children().toArray().map((element) => ({
    type: element.tagName === "pre" ? "code" : "paragraph",
    display: toMarkdown(element),
    element,
  }));
  return { title: ${JSON.stringify(title)}, units };
}
`;
}

async function extractUnits(body: string, title = TITLE): Promise<Unit[]> {
  const result = await runRecipe(env, childrenRecipe(title), articleWith(body));
  if (!result.ok) {
    throw new Error(JSON.stringify(result.report));
  }
  return result.units;
}

describe("the markdown a declared element converts to", () => {
  it("a blockquote keeps its quote markers on every line, a quoted blank line between paragraphs", async () => {
    const units = await extractUnits("<blockquote><p>First thought.</p><p>Second thought.</p></blockquote>");

    expect(units).toEqual([
      { type: "paragraph", display: "> First thought.\n> \n> Second thought." },
    ]);
  });

  it("an ordered list keeps its start number and indents a nested bullet list", async () => {
    const units = await extractUnits(
      '<ol start="3"><li>Third<ul><li>Aside</li></ul></li><li>Fourth</li></ol>',
    );

    expect(units).toHaveLength(1);
    expect(units[0].display).toMatch(/^3\.\s+Third\n\s+-\s+Aside\n4\.\s+Fourth$/);
  });

  it("a table with a header row becomes a pipe table", async () => {
    const units = await extractUnits(
      "<table><thead><tr><th>Name</th><th>Role</th></tr></thead><tbody><tr><td>Ada</td><td>Author</td></tr></tbody></table>",
    );

    expect(units).toEqual([
      { type: "paragraph", display: "| Name | Role |\n| --- | --- |\n| Ada | Author |" },
    ]);
  });

  it("a table without a header row becomes a pipe table headed by its first row", async () => {
    const units = await extractUnits(
      "<table><tr><td>Name</td><td>Role</td></tr><tr><td>Ada</td><td>Author</td></tr></table>",
    );

    expect(units).toEqual([
      { type: "paragraph", display: "| Name | Role |\n| --- | --- |\n| Ada | Author |" },
    ]);
  });

  it("a pre with a code child and a bare pre both become fenced code units", async () => {
    const units = await extractUnits("<pre><code>x = 1</code></pre><pre>y = 2</pre>");

    expect(units).toEqual([
      { type: "code", display: "```\nx = 1\n```" },
      { type: "code", display: "```\ny = 2\n```" },
    ]);
  });

  it("struck-through text is doubled tildes and a task list keeps its checkboxes", async () => {
    const units = await extractUnits(
      '<p>Plans <del>abandoned</del> kept.</p><ul><li><input type="checkbox" checked> Done</li><li><input type="checkbox"> Pending</li></ul>',
    );

    expect(units[0].display).toBe("Plans ~~abandoned~~ kept.");
    expect(units[1].display).toMatch(/^-\s+\[x\] Done\n-\s+\[ \] Pending$/);
  });

  it("inline elements with no markdown form keep only their text", async () => {
    const units = await extractUnits(
      "<p>Press <kbd>Ctrl</kbd> to <mark>highlight</mark> the 2<sup>nd</sup> line.</p>",
    );

    expect(units).toEqual([{ type: "paragraph", display: "Press Ctrl to highlight the 2nd line." }]);
  });

  it("a plain paragraph converts unchanged", async () => {
    const units = await extractUnits("<p>Just <em>one</em> sentence.</p>");

    expect(units).toEqual([{ type: "paragraph", display: "Just _one_ sentence." }]);
  });
});

import type { CheerioAPI } from "cheerio/slim";
import type { AnyNode, Element } from "domhandler";
import type { Unit } from "../units.ts";
import { toMarkdown } from "./markdown.ts";

const BLOCK_SELECTOR = "pre, img, figure, picture, svg";

type Piece = { kind: "content"; node: AnyNode } | { kind: "block"; unit: Unit };

function isElement(node: AnyNode): node is Element {
  return node.type === "tag" || node.type === "script" || node.type === "style";
}

// A <figure> is only an image when it carries one: a <figure> wrapping a
// highlighted listing holds a <pre>, which has to surface as code instead.
function isBlock($: CheerioAPI, element: Element): boolean {
  if (element.name === "figure") {
    return $(element).find("img").length > 0;
  }
  return ["pre", "img", "picture", "svg"].includes(element.name);
}

export function holdsBlock($: CheerioAPI, element: Element): boolean {
  return $(element).find(BLOCK_SELECTOR).length > 0;
}

function blockUnit($: CheerioAPI, block: Element): Unit {
  if (block.name === "pre") {
    return { type: "code", display: toMarkdown(block) };
  }

  const $image = block.name === "figure" || block.name === "picture" ? $(block).find("img").first() : $(block);
  const alt = $image.attr("alt") ?? "";
  return { type: "image", display: alt, src: $image.attr("src") ?? "", alt };
}

// Whitespace left between tags once a nested list or a block is pulled out of
// an item carries nothing; wrapping it would open a spurious empty item.
function isMeaningful(node: AnyNode): boolean {
  if (node.type === "text") {
    return node.data.trim().length > 0;
  }
  return isElement(node);
}

function splitNode($: CheerioAPI, node: AnyNode): Piece[] {
  if (!isElement(node)) {
    return [{ kind: "content", node: $(node).clone().get(0) as AnyNode }];
  }

  if (isBlock($, node)) {
    return [{ kind: "block", unit: blockUnit($, node) }];
  }

  if (!holdsBlock($, node)) {
    return [{ kind: "content", node: $(node).clone().get(0) as AnyNode }];
  }

  return splitAround($, node);
}

// Every run of content between two blocks goes back into a copy of the
// element it came from, so an item resumed after a block reopens as an empty
// <li> at each level above it, and an ordered part starts at the number of
// the first item it carries.
function splitAround($: CheerioAPI, element: Element): Piece[] {
  const pieces: Piece[] = [];
  let run: AnyNode[] = [];
  let runStart: number | null = null;

  const flush = () => {
    if (run.some(isMeaningful)) {
      const part = $(element).clone().empty();
      part.append(run);

      if (element.name === "ol" && runStart != null) {
        part.attr("start", String(runStart));
      }

      pieces.push({ kind: "content", node: part.get(0) as AnyNode });
    }

    run = [];
    runStart = null;
  };

  let number = Number.parseInt($(element).attr("start") ?? "1", 10);
  for (const child of element.children) {
    const isItem = isElement(child) && child.name === "li";
    const childNumber = number;
    if (isItem) {
      number += 1;
    }

    for (const piece of splitNode($, child)) {
      if (piece.kind === "block") {
        flush();
        pieces.push(piece);
        continue;
      }

      if (isItem && runStart == null) {
        runStart = childNumber;
      }
      run.push(piece.node);
    }
  }
  flush();

  return pieces;
}

export function splitList($: CheerioAPI, list: Element): Unit[] {
  return splitAround($, list).map((piece) =>
    piece.kind === "block" ? piece.unit : { type: "paragraph", display: toMarkdown(piece.node) },
  );
}

